"""Public plant relationships without private diagnostic candidates."""
from historiansim.plants.base import PlantDescription,Section
def describe(cfg):
    return PlantDescription(title='P-27 stamping cell',intro=['A servo feeder advances cold rolled strip through one stamping press. Each completed permitted stroke produces one piece. It reaches the optical inspection station ten seconds later.'],sections=[
      Section('Service and design basis',['The synthetic design uses 60 strokes/min, 100 mm pitch, 100 mm strip width and 1.2 mm thickness. Density is 7850 kg/m3. Forming work is 1000 J per cycle at design. These assumptions do not represent a calibrated machine.']),
      Section('Equipment and flow',['A decoiler supplies a loop buffer. The servo feeder advances strip to the press. A circulating lubrication circuit supplies the bearings. Cooling water removes die heat. Pieces reach dimensional inspection after ten seconds. Two independent optical gauges acquire each arriving part. The PLC classifies accepted/rejected pieces from the primary measured gauge against 100 mm ±0.25 mm, and records pending in-transit pieces separately.']),
      Section('Physical relationships',['Motor energy supplies forming work, bearing dissipation, other losses and flywheel storage. Force integrates over 20 mm of ram displacement to the forming work. Strip strength and thickness influence forming demand. Die guide alignment influences transverse force difference.','The controlled speed is the mean envelope speed. The independent tachometer includes the phase energy demand. The controlled feeder value is the last completed shaft-encoder travel, held between events. Independent strip progression checks actual travel. Shaft and strip endpoints are latched when a feed begins, and that same completed strip travel debits material; a changing command is scheduled for the next cycle. Within-cycle travel coordinates reset at the completed-stroke count boundary. Buffer inflow minus completed pitch withdrawals determines inventory.','Header pressure depends on pump delivery, oil viscosity, bearing demand and return leakage. Filter differential depends on flow and hydraulic resistance. Film flow is a separate branch measurement. Die temperature depends on forming heat and coolant duty. Product dimension depends on die temperature, thickness and completed pitch. Independent check samples share the physical part and transport delay.']),
      Section('Control strategy',['Five native feedback loops regulate mean speed, completed feeder pitch, mean inventory, lubrication pressure and die temperature. Every controller reads its measured transmitter. Inventory control is deliberately loose. Modes, setpoints and output demands are separate records.']),
      Section('Acquisition and accounting',['Pulse-count positions and speeds use 16-bit digital quantization with no invented liquid-level or turbulent-flow sensor dynamics. Controllers read the same quantized digital transmitter including calibration gain errors. Analogue zero-centered force, displacement and drain instruments have signed measurement margins; true force and flow remain nonnegative.','Optical gauge acquisition occurs at each actual part delivery, before historian sampling. Its 10 micrometre output quantization and independent 50 micrometre thermal/illumination uncertainty are explicit synthetic instrument assumptions. The accepted/rejected counters use acquired readings, including calibration errors; they are not hidden true-quality labels. Completed pieces equal accepted plus rejected plus pending inspection. Historian node outages affect exported quality while the local PLC continues classification.','The interlocked clutch preserves partial stroke and feed work during an operator stop. It brakes/coasts and spins up before re-engagement. The public digital journal uses a 1 ms clock and redacts payloads with unavailable acquisition quality.']),
      'tags','calcs','instruments',Section('External influences',['Material strength and thickness, supply voltage, cooling water and ambient conditions vary on named stochastic streams.']), 'neighbours','files'],tag_notes={},calc_definitions=[('CALC-WORK','WI-271 × 1000 × 0.02 / 2','Measured peak force integrated over triangular 20 mm forming travel.'),('CALC-SUPPLY','FI-275','Measured decoiler delivery.'),('CALC-CONSUMPTION','ZI-272 × 0.001 × SIC-271.PV / 60 × DI-271','Measured progression times speed while permitted.'),('CALC-TRAVEL-GAP','ZI-276 − ZI-272','Independent measured shaft travel minus strip travel.')],calc_notes=[],instrument_notes=['The model resolves lumped envelope behavior. It does not model tooling finite elements or high-frequency vibration.'])
